(()=>{'use strict';function hook(){const l1=window.CCNERLevel1;if(!l1)return false;if(!window.__ccnerL1QuickHook){document.addEventListener('click',e=>{const b=e.target.closest?.('[data-q]');if(!b)return;const a=b.dataset.q;if(a==='stories'||a==='music'){e.preventDefault();e.stopImmediatePropagation();l1.open(a==='stories'?'stories':'music')}},true);window.__ccnerL1QuickHook=true}if(typeof window.respond==='function'&&!window.__ccnerL1RespondHook){const original=window.respond;window.respond=function(text){try{const modal=document.querySelector('#l3MomoModal'),log=document.querySelector('#l3Log');if(modal&&log&&l1.momoMemory(text,log)){const note=document.createElement('div');note.className='l3-chat momo';note.textContent='Momo: I found a saved family memory that may fit this conversation.';log.appendChild(note);log.scrollTop=log.scrollHeight}}catch(_){}return original.apply(this,arguments)};window.__ccnerL1RespondHook=true}return true}function boot(){if(!hook()){let n=0;const i=setInterval(()=>{if(hook()||++n>20)clearInterval(i)},300)}}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot()})();